INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q1425362', 'Battle of Cajamarca', 'The Battle of Cajamarca, also spelled Cajamalca (though many contemporary scholars prefer to call it the Cajamarca massacre), was the ambush and seizure of the Incan ruler Atahualpa by a small Spanish force led by Francisco Pizarro, on November 16, 1532. The Spanish killed thousands of Atahualpa''s counselors, commanders, and unarmed attendants in the great plaza of Cajamarca, and caused his armed host outside the town to flee.', 1532, 11, 16, NULL, NULL, NULL, 'day', '16 November 1532', 61, 'https://en.wikipedia.org/wiki/Battle_of_Cajamarca'),
  ('Q1612814', 'Battle of Cusco', 'The Battle of Cusco was fought in November 1533 between the Spanish Conquistadors and forces of the Incas.', 1533, 11, 14, 1533, 11, 15, 'day', '14 November 1533 – 15 November 1533', 39, 'https://en.wikipedia.org/wiki/Battle_of_Cusco'),
  ('Q2398589', 'Siege of Cusco', 'The 10-month siege of Cusco by the Incan army under the command of Sapa Inca Manco Inca Yupanqui started on 6 May 1536 and ended in March 1537. The city was held by a garrison of Spanish conquistadors and Indian auxiliaries led by Hernando Pizarro.', 1536, 5, 6, 1537, 4, 18, 'day', '6 May 1536 – 18 April 1537', 50, 'https://en.wikipedia.org/wiki/Siege_of_Cusco'),
  ('Q2338569', 'Battle of Ollantaytambo', 'The Battle of Ollantaytambo (Spanish: Batalla de Ollantaytambo, IPA: [baˈtaʎa ðe oʎantajˈtambo]) took place in January 1537, between the forces of Inca emperor Manco Inca and a Spanish expedition led by Hernando Pizarro during the Spanish conquest of Peru. A former ally of the Spaniards, Manco Inca rebelled in May 1536, and besieged a Spanish garrison in the city of Cusco.', 1537, 1, NULL, NULL, NULL, NULL, 'month', 'January 1537', 47, 'https://en.wikipedia.org/wiki/Battle_of_Ollantaytambo'),
  ('Q947591', 'Battle of Las Salinas', 'The Battle of Las Salinas was a military conflict and decisive confrontation between the forces of Hernando and Gonzalo Pizarro against those of rival conquistador Diego de Almagro, on April 26, 1538, during the Conquest of Peru. Both camps claimed to represent the authority of the Spanish Crown; Pizarro''s forces controlled the province of Nueva Castilla, and those of Almagro, Nueva Toledo.', 1538, 4, 26, NULL, NULL, NULL, 'day', '26 April 1538', 47, 'https://en.wikipedia.org/wiki/Battle_of_Las_Salinas'),
  ('Q1612597', 'Battle of Chupas', 'After the assassination of Francisco Pizarro, in retaliation for his father''s execution in 1538, Diego de Almagro II, El Mozo, continued to press claims as the rightful ruler of Peru and as leader of his father''s supporters. His claims were largely unsuccessful, however, as Pizarro was succeeded as governor by Cristóbal Vaca de Castro, despite claims from his brother Gonzalo Pizarro, whose claims to join arms against the Almagristas and "El Mozo" largely remained unanswered.', 1542, 9, 16, NULL, NULL, NULL, 'day', '16 September 1542', 39, 'https://en.wikipedia.org/wiki/Battle_of_Chupas'),
  ('Q2338093', 'Battle of Jaquijahuana', 'The Battle of Jaquijahuana was fought between the forces of Gonzalo Pizarro and Pedro de la Gasca, on April 9, 1548, during the Revolt of the Encomenderos by the Spanish conquistadores. After the successful Spanish conquest of the Inca Empire, the assassination of Francisco Pizarro in 1541, and the execution of his main antagonist, Diego de Almagro (1538) and his son, El Mozo (1542), most of the competent commanders of the recently founded New Castile Governorate had been lost in the ensuing power struggle.', 1548, 4, 9, NULL, NULL, NULL, 'day', '9 April 1548', 39, 'https://en.wikipedia.org/wiki/Battle_of_Jaquijahuana'),
  ('Q4551867', '1687 Peru earthquake', 'The 1687 Peru earthquake occurred at 11:30 UTC on 20 October 1687. It had an estimated magnitude of 8.4–8.7 and caused severe damage to Lima, Callao and Ica.', 1687, NULL, NULL, NULL, NULL, NULL, 'year', '1687', 37, 'https://en.wikipedia.org/wiki/1687_Peru_earthquake'),
  ('Q4552798', '1746 Lima - Callao earthquake', 'The 1746 Lima–Callao earthquake occurred at 22:30 local time on 28 October with a moment magnitude of 8.6–8.8 and a maximum Mercalli intensity of XI (Extreme). The epicenter was located about 90 km (56 mi) north-northwest of the capital Lima, which was almost completely destroyed, and the subsequent tsunami devastated the port city of Callao.', 1746, 10, 28, NULL, NULL, NULL, 'day', '28 October 1746', 37, 'https://en.wikipedia.org/wiki/1746_Lima%E2%80%93Callao_earthquake'),
  ('Q1806552', 'Rebellion of Túpac Amaru II', 'The Rebellion of Túpac Amaru II was an uprising by kuraka-led Aymara, Quechua, and mestizo rebels aimed at overthrowing Spanish colonial rule in Peru, from 1780 to 1783. The causes of the rebellion included opposition to the Bourbon Reforms, an economic downturn in colonial Peru, and a grassroots revival of Inca cultural identity led by Túpac Amaru II, an indigenous kuraka and the leader of the rebellion.', 1780, 11, 4, 1783, 3, 15, 'day', '4 November 1780 – 15 March 1783', 45, 'https://en.wikipedia.org/wiki/Rebellion_of_T%C3%BApac_Amaru_II'),
  ('Q68478', 'Peruvian War of Independence', 'The Peruvian War of Independence (Spanish: Guerra de Independencia del Perú) was a series of military conflicts in Peru from 1809 to 1826. Part of the broader Spanish American wars of independence, it led to the dissolution of the Spanish Viceroyalty of Peru and the emergence of Peru as an independent state on 28 July 1821.', 1821, NULL, NULL, 1824, NULL, NULL, 'year', '1821–1824', 61, 'https://en.wikipedia.org/wiki/Peruvian_War_of_Independence'),
  ('Q934157', 'Battle of Ayacucho', 'The Battle of Ayacucho (Spanish: Batalla de Ayacucho, IPA: [baˈtaʎa ðe aʝaˈkutʃo]) was a decisive military encounter during the Peruvian War of Independence. This battle secured the independence of Peru and ensured independence for the rest of belligerent South American states.', 1824, 12, 9, NULL, NULL, NULL, 'day', '9 December 1824', 66, 'https://en.wikipedia.org/wiki/Battle_of_Ayacucho'),
  ('Q1508820', 'Battle of Junín', 'The Battle of Junín was a large cavalry engagement of the Peruvian War of Independence, fought in the highlands of the Junín Region on 6 August 1824. The preceding February the royalists had regained control of Lima, and having regrouped in Trujillo, Simón Bolívar in June led his rebel forces south to confront the Spanish under Field Marshal José de Canterac.', 1824, 8, 6, NULL, NULL, NULL, 'day', '6 August 1824', 56, 'https://en.wikipedia.org/wiki/Battle_of_Jun%C3%ADn'),
  ('Q5887865', 'Salaverry-Santa Cruz War', 'The Salaverry-Santa Cruz War, sometimes called the Peruvian Civil War of 1835–1836, was an internal conflict in Peru with the involvement of the Bolivian army of Andres de Santa Cruz. It ended with the defeat and execution of Felipe Santiago Salaverry and the creation of the Peru–Bolivian Confederation.', 1835, NULL, NULL, 1836, NULL, NULL, 'year', '1835–1836', 37, 'https://en.wikipedia.org/wiki/Salaverry-Santa_Cruz_War'),
  ('Q601811', 'War of the Confederation', 'The War of the Confederation (Spanish: Guerra de la Confederación) was a military confrontation waged by the United Restoration Army, the alliance of the land and naval forces of Chile and the Restoration Army of Peru, formed in 1836 by Peruvian soldiers opposed to the confederation, and the Argentine Confederation against the Peru–Bolivian Confederation between 1836 and 1839. As a result of the Salaverry-Santa Cruz War, the Peru–Bolivian Confederation was created by General Andrés de Santa Cruz, which caused a power struggle in southern South America, with Chile and the Argentine…', 1836, NULL, NULL, 1839, 8, 15, 'year', '1836 – 15 August 1839', 57, 'https://en.wikipedia.org/wiki/War_of_the_Confederation'),
  ('Q2890439', 'Battle of Yungay', 'The Battle of Yungay (or Yungai) was the final battle of the War of the Confederation, fought on January 20, 1839, near Yungay, Peru. The United Restoration Army, led by Chilean General Manuel Bulnes, consisting mainly of Chileans and 600 North Peruvian dissidents, attacked the Peru-Bolivian Confederation forces led by Andrés de Santa Cruz in northern Peru, 200 kilometers (120 mi) north of Lima.', 1839, 1, 20, NULL, NULL, NULL, 'day', '20 January 1839', 48, 'https://en.wikipedia.org/wiki/Battle_of_Yungay'),
  ('Q495202', 'Guerra de la Union y la Fuerza', 'The Peruvian–Bolivian War was a warlike confrontation between Peru and Bolivia in the years 1841 and 1842. In 1841, Agustín Gamarra, President of Peru, tried to annex Bolivia, which cost the Peruvian president his life on November 18, 1841 at the Battle of Ingavi.', 1841, 10, 1, 1842, 6, 7, 'day', '1 October 1841 – 7 June 1842', 41, 'https://en.wikipedia.org/wiki/Peruvian%E2%80%93Bolivian_War_of_1841%E2%80%9342'),
  ('Q3119117', 'Ecuadorian–Peruvian War of 1857–1860', 'The First Ecuadorian–Peruvian War took place between 1857 and 1860. The conflict began when Ecuador attempted to sell Amazon basin land claimed by Peru in order to settle a debt with British creditors.', 1857, NULL, NULL, 1860, 1, 25, 'year', '1857 – 25 January 1860', 39, 'https://en.wikipedia.org/wiki/Ecuadorian%E2%80%93Peruvian_War_(1857%E2%80%931860)'),
  ('Q2394918', 'Battle of Callao', 'The Battle of Callao (Spanish: Combate del Dos de Mayo, as it is known in South America) occurred on May 2, 1866, between a Spanish fleet under the command of Admiral Casto Méndez Núñez and the fortified battery emplacements of the Peruvian port city of Callao during the Chincha Islands War. The Spanish fleet bombarded the port of Callao (or El Callao), and eventually withdrew without any notable damage to the city structures, according to the Peruvian and American sources; or after having silenced almost all the guns of the coastal defenses, according to the Spanish accounts and French…', 1866, 5, 2, NULL, NULL, NULL, 'day', '2 May 1866', 47, 'https://en.wikipedia.org/wiki/Battle_of_Callao'),
  ('Q3271607', '1868 Arica earthquake', 'The 1868 Arica earthquake occurred on 13 August 1868, near Arica, then part of Peru, now part of Chile, at 21:30 UTC. It had an estimated magnitude between 8.8 and 9.1, although earlier studies suggested a broader range of 8.5–9.3. A tsunami (or multiple tsunamis) in the Pacific Ocean was produced by the earthquake, which was recorded in Hawaii, Japan, Australia, and New Zealand.', 1868, 8, 13, NULL, NULL, NULL, 'day', '13 August 1868', 50, 'https://en.wikipedia.org/wiki/1868_Arica_earthquake'),
  ('Q1161889', '1877 Iquique earthquake', 'The 1877 Iquique earthquake occurred at 21:16 local time on 9 May (10 May UTC). It had a magnitude of 8.5 on the surface-wave magnitude scale.', 1877, NULL, NULL, NULL, NULL, NULL, 'year', '1877', 39, 'https://en.wikipedia.org/wiki/1877_Iquique_earthquake'),
  ('Q152004', 'War of the Pacific', 'The War of the Pacific (Spanish: Guerra del Pacífico), also known by multiple other names, was a war between Chile and a Bolivian–Peruvian alliance from 1879 to 1884. Fought over Chilean claims on coastal Bolivian territory in the Atacama Desert, the war ended with victory for Chile, which gained a significant amount of resource-rich territory from Peru and Bolivia.', 1879, 4, 5, 1884, 4, 4, 'day', '5 April 1879 – 4 April 1884', 79, 'https://en.wikipedia.org/wiki/War_of_the_Pacific'),
  ('Q275736', 'Battle of San Francisco', 'The Battle of San Francisco, also known as the Battle of Dolores, was a major battle in the Tarapacá Campaign of the War of the Pacific, fought on November 19, 1879, in the Peruvian department of Tarapacá. A Chilean army under Colonel Emilio Sotomayor had moved via Dolores rail road deep into the desert and was encamped at San Francisco Saltpeter Office, about 30 kilometers south east of the port of Pisagua.', 1879, 11, 19, NULL, NULL, NULL, 'day', '19 November 1879', 34, 'https://en.wikipedia.org/wiki/Battle_of_San_Francisco'),
  ('Q472672', 'Battle of Iquique', 'The Battle of Iquique was a naval engagement on 21 May 1879, during the War of the Pacific, where a Chilean corvette commanded by Arturo Prat Chacón faced a Peruvian ironclad under Miguel Grau. The battle occurred off the port of Iquique, Peru, and ended with the sinking of the Chilean wooden corvette Esmeralda by the Peruvian ironclad Huáscar after four hours of combat, marking a victory for Peru.', 1879, 5, 21, NULL, NULL, NULL, 'day', '21 May 1879', 53, 'https://en.wikipedia.org/wiki/Battle_of_Iquique'),
  ('Q33930847', 'Putumayo genocide', 'The Putumayo genocide (Spanish: genocidio del Putumayo) refers to the severe exploitation and subsequent ethnocide of the Indigenous population in the Putumayo region. The booms of raw materials incentivized the exploration and occupation of uncolonised land in the Amazon by several South American countries, gradually leading to the subjugation of the local tribes in the pursuit of rubber extraction.', 1879, NULL, NULL, 1912, NULL, NULL, 'year', '1879–1912', 41, 'https://en.wikipedia.org/wiki/Putumayo_genocide'),
  ('Q18014904', 'Battle of Tacna', 'The Battle of Tacna, also known as the Battle of the Alto de la Alianza, was a battle that took place on May 26, 1880, at the plateau of the Alto de la Alianza, a hill a few miles north of the Peruvian city of Tacna. It effectively destroyed the Peru-Bolivian alliance against Chile, forged by a secret treaty signed in 1873.', 1880, 5, 26, NULL, NULL, NULL, 'day', '26 May 1880', 47, 'https://en.wikipedia.org/wiki/Battle_of_Tacna'),
  ('Q2889343', 'Battle of Miraflores', 'The Battle of Miraflores occurred on January 15, 1881 in the Miraflores District of Lima, Peru. It was an important battle during the War of the Pacific that was fought between Chile and the forces of Peru.', 1881, 1, 15, NULL, NULL, NULL, 'day', '15 January 1881', 39, 'https://en.wikipedia.org/wiki/Battle_of_Miraflores'),
  ('Q956098', 'Battle of La Concepción', 'The Battle of La Concepción (Spanish: Batalla de Concepción) was fought between Chilean and Peruvian forces on July 9 and 10, 1882, during the Breña campaign of the War of the Pacific. Heavily outnumbered, the Chilean detachment of 77 men under the command of Captain Ignacio Carrera Pinto was annihilated by a 1,300-strong Peruvian force, many of them armed with spears, commanded by Col.', 1882, 7, 10, NULL, NULL, NULL, 'day', '10 July 1882', 41, 'https://en.wikipedia.org/wiki/Battle_of_La_Concepci%C3%B3n'),
  ('Q1475005', 'Treaty of Ancón', 'The Treaty of Ancón was a peace treaty signed by Chile and Peru on 20 October 1883, in Ancón, near Lima. It was intended to settle the two nations'' remaining territorial differences at the conclusion of their involvement in the War of the Pacific and to stabilise post-bellum relations between them.', 1883, NULL, NULL, NULL, NULL, NULL, 'year', '1883', 47, 'https://en.wikipedia.org/wiki/Treaty_of_Anc%C3%B3n'),
  ('Q5887721', 'Peruvian Civil War of 1894–1895', 'The Peruvian Civil War of 1894–1895 was an internal conflict in Peru that lasted from October 1894 to March 1895, and was sparked by the election of Andrés Avelino Cáceres to the presidency of Peru, which was opposed by Nicolás de Piérola and his armed forces. The immediate cause of the conflict was the questioned election of Cáceres in 1894, carried out outside the constitutional framework, but the fundamental cause was the need to end the hegemony of the Constitutional (or Cacerist) Party, in power since 1886, and with the rise of militarism in the political scenario, the so-called Second…', 1894, 10, 24, 1895, 3, 19, 'day', '24 October 1894 – 19 March 1895', 34, 'https://en.wikipedia.org/wiki/Peruvian_Civil_War_of_1894%E2%80%931895'),
  ('Q2990714', 'Treaty of Lima', 'The Treaty of Lima was a boundary treaty signed on June 3, 1929. The agreement put an end to the territorial dispute regarding the provinces of Tacna and Arica, which had been administered by Chile since 1883.', 1929, 6, 3, NULL, NULL, NULL, 'day', '3 June 1929', 39, 'https://en.wikipedia.org/wiki/Treaty_of_Lima_(1929)'),
  ('Q1536533', 'Colombian-Peruvian War', 'The Colombia–Peru War, also called the Leticia War, was a short-lived armed conflict between Colombia and Peru over territory in the Amazon rainforest that lasted from September 1, 1932, to May 24, 1933. In the end, an agreement was reached to divide the disputed area between both countries.', 1932, 9, 1, 1933, 6, 25, 'day', '1 September 1932 – 25 June 1933', 57, 'https://en.wikipedia.org/wiki/Colombia%E2%80%93Peru_War'),
  ('Q1500631', 'Ecuadorian–Peruvian War', 'The Second Ecuadorian–Peruvian War, usually called simply the Ecuadorian–Peruvian War, and known locally as the War of ''41 (Spanish: Guerra del 41), was a South American war fought between 5 July to 2 October of 1941. It was the first of three military conflicts between Ecuador and Peru during the 20th century.', 1942, 1, 31, 1942, 1, 29, 'day', '31 January 1942 – 29 January 1942', 62, 'https://en.wikipedia.org/wiki/Ecuadorian%E2%80%93Peruvian_War'),
  ('Q1801868', 'Rio Protocol', 'The Protocol of Peace, Friendship, and Boundaries between Peru and Ecuador, or Rio Protocol for short, was an international agreement signed in Rio de Janeiro, Brazil, on January 29, 1942, by the foreign ministers of Peru and Ecuador, with the participation of the United States, Brazil, Chile, and Argentina as guarantors. The Protocol was intended to finally resolve the long-running territorial dispute between the two countries, and brought about the official end of the Ecuadorian–Peruvian War of 1941–1942.', 1942, 1, 29, NULL, NULL, NULL, 'day', '29 January 1942', 52, 'https://en.wikipedia.org/wiki/Rio_Protocol'),
  ('Q18471510', 'Varig Flight 810', 'Varig Flight 810 was a scheduled international passenger flight from Rio de Janeiro to Los Angeles with stopovers in Lima, Bogotá, Panama City, and Mexico City. On 27 November 1962, the Boeing 707 operating the route crashed into a mountain on an approach to Lima, killing all 97 passengers and crew.', 1962, 11, 27, NULL, NULL, NULL, 'day', '27 November 1962', 45, 'https://en.wikipedia.org/wiki/Varig_Flight_810'),
  ('Q3245204', '1970 Ancash earthquake', 'The 1970 Ancash earthquake (also known as the Great Peruvian earthquake) occurred on 31 May off the coast of Peru in the Pacific Ocean at 15:23:29 local time. Combined with a resultant landslide, it is the most catastrophic natural disaster in the history of Peru.', 1970, 5, 31, NULL, NULL, NULL, 'day', '31 May 1970', 61, 'https://en.wikipedia.org/wiki/1970_Ancash_earthquake'),
  ('Q1797867', 'LANSA Flight 508', 'LANSA Flight 508 was a Lockheed L-188A Electra turboprop operated as a scheduled domestic passenger flight by Lineas Aéreas Nacionales Sociedad Anonima (LANSA) that crashed in a thunderstorm en route from Lima to Pucallpa in Peru on 24 December 1971, killing 91 people – all 6 crew on board and 85 of its 86 passengers. As a result of a lightning bolt strike to the right-hand wing, the aircraft crashed down into the Amazon rainforest.', 1971, 12, 24, NULL, NULL, NULL, 'day', '24 December 1971', 57, 'https://en.wikipedia.org/wiki/LANSA_Flight_508'),
  ('Q3029749', 'Barrios Altos massacre', 'The Barrios Altos massacre (Spanish: Masacre de Barrios Altos) occurred on 3 November 1991 in the Barrios Altos neighborhood of Lima, Peru. Members of Grupo Colina, a death squad comprising Peruvian Armed Forces personnel, were later identified as the assailants who killed fifteen individuals, including an eight-year-old child, and injured four others.', 1991, 11, 3, NULL, NULL, NULL, 'day', '3 November 1991', 39, 'https://en.wikipedia.org/wiki/Barrios_Altos_massacre'),
  ('Q5918256', 'La Cantuta massacre', 'The La Cantuta massacre took place in Peru on 18 July 1992, during the presidency of Alberto Fujimori. Supposed members of Shining Path, including a university professor and nine students from Lima''s La Cantuta University, were abducted, tortured, and killed by Grupo Colina, a military death squad.', 1992, 7, 18, NULL, NULL, NULL, 'day', '18 July 1992', 39, 'https://en.wikipedia.org/wiki/La_Cantuta_massacre'),
  ('Q2337340', 'Cenepa War', 'The Cenepa War (26 January – 28 February 1995), also known as the Alto Cenepa War, was a brief and localized military conflict between Ecuador and Peru, fought over control of an area in the Ecuadorian territory (i.e. in the eastern side of the Cordillera del Cóndor, Province of Condorcanqui, Región Amazonas, Republic of Ecuador) near the border between the two countries.', 1995, 1, 26, 1995, 2, 28, 'day', '26 January 1995 – 28 February 1995', 53, 'https://en.wikipedia.org/wiki/Cenepa_War'),
  ('Q381615', 'Aeroperú Flight 603', 'Aeroperú Flight 603 was a scheduled passenger flight from Miami International Airport in Miami, Florida, United States, to Arturo Merino Benítez International Airport in Santiago, Chile, with stopovers in Quito, Ecuador, and Lima, Peru. On October 2, 1996, the Boeing 757 aircraft flying the final leg of the flight crashed into the Pacific Ocean.', 1996, 10, 2, NULL, NULL, NULL, 'day', '2 October 1996', 61, 'https://en.wikipedia.org/wiki/Aeroper%C3%BA_Flight_603'),
  ('Q5438057', 'Faucett Flight 251', 'Faucett Perú Flight 251 was a scheduled domestic flight from Lima to Tacna, with a stopover in Arequipa. On 29 February 1996, while completing the first leg, the Boeing 737-200 operating the route crashed on approach to Rodríguez Ballón International Airport.', 1996, 2, 29, NULL, NULL, NULL, 'day', '29 February 1996', 50, 'https://en.wikipedia.org/wiki/Faucett_Per%C3%BA_Flight_251'),
  ('Q15991253', 'Brasilia Presidential Act', 'The Brasilia Presidential Act (Spanish: Acta Presidencial de Brasilia, Portuguese: Ato Presidencial de Brasília), also known as the Fujimori–Mahuad Treaty (Spanish: Tratado Fujimori–Mahuad), is an international treaty signed in Brasília by the then President of Ecuador, Jamil Mahuad and then President of Peru, Alberto Fujimori, which effectively put an end to the Ecuadorian–Peruvian territorial dispute.', 1998, 10, 26, NULL, NULL, NULL, 'day', '26 October 1998', 37, 'https://en.wikipedia.org/wiki/Brasilia_Presidential_Act'),
  ('Q2625364', '2001 southern Peru earthquake', 'The 2001 southern Peru earthquake occurred at 20:33:15 UTC (15:33:15 local time) on June 23 with a moment magnitude of 8.4 and a maximum Mercalli intensity of VIII (Severe). The quake affected the Peruvian regions of Arequipa, Moquegua and Tacna.', 2001, 6, 23, NULL, NULL, NULL, 'day', '23 June 2001', 43, 'https://en.wikipedia.org/wiki/2001_southern_Peru_earthquake'),
  ('Q7669317', 'TANS Perú Flight 222', 'TANS Peru Flight 222 was a domestic passenger flight from Lima, Peru to Chachapoyas with a stopover at Chiclayo, which crashed on 9 January 2003. The flight was operated by a Fokker F28-1000 Fellowship short range airliner.', 2003, 1, 9, NULL, NULL, NULL, 'day', '9 January 2003', 48, 'https://en.wikipedia.org/wiki/TANS_Per%C3%BA_Flight_222'),
  ('Q2648885', 'TANS Perú Flight 204', 'TANS Perú Flight 204 was a domestic scheduled Lima–Pucallpa–Iquitos passenger service, operated with a Boeing 737-200, that crashed on 23 August 2005 on approach to Pucallpa Airport, 4 miles (6.4 km) off the airfield, following an emergency landing attempt because of bad weather, killing 40 of the 98 passengers and crew aboard.', 2005, 8, 23, NULL, NULL, NULL, 'day', '23 August 2005', 60, 'https://en.wikipedia.org/wiki/TANS_Per%C3%BA_Flight_204'),
  ('Q210981', '2007 Peru earthquake', 'The 2007 Peru earthquake, which measured 8.0 on the moment magnitude scale, hit the central coast of Peru on August 15 at 23:40:57 UTC (18:40:57 local time) and lasted two minutes. The epicenter was located 150 km (93 mi) south-southeast of Lima at a depth of 39 km (24 mi).', 2007, 8, 15, NULL, NULL, NULL, 'day', '15 August 2007', 68, 'https://en.wikipedia.org/wiki/2007_Peru_earthquake'),
  ('Q16004619', '2014 Iquique earthquake', 'The 2014 Iquique earthquake struck off the coast of Chile on 1 April, with a moment magnitude of 8.1–8.2, at 20:46 local time (23:46 UTC). The epicenter of the earthquake was approximately 95 kilometres (59 mi) northwest of Iquique.', 2014, 4, 1, NULL, NULL, NULL, 'day', '1 April 2014', 57, 'https://en.wikipedia.org/wiki/2014_Iquique_earthquake'),
  ('Q28949969', '2017 Peru floods', 'From December 2016 and continuing until May 2017, much of western and central South America was plagued by persistent heavy rain events. In Peru, one of the most severely impacted nations, it has been referred to as the 2017 Coastal Niño (Spanish: El Niño costero de 2017).', 2017, NULL, NULL, NULL, NULL, NULL, 'year', '2017', 43, 'https://en.wikipedia.org/wiki/2016%E2%80%9317_South_American_floods'),
  ('Q47354608', '2018 Peru earthquake', 'An earthquake struck Peru at 04:18:45 PET (09:18:45 UTC) on 14 January 2018. It had a magnitude of Mww 7.1 with a maximum perceived intensity of VII (very strong) on the Mercalli intensity scale.', 2018, 1, 14, NULL, NULL, NULL, 'day', '14 January 2018', 45, 'https://en.wikipedia.org/wiki/2018_Peru_earthquake'),
  ('Q64031974', '2019 Peru earthquake', 'An earthquake measuring Mw 8.0 struck Peru and the surrounding areas on 26 May 2019 at 02:41 local time. It had a maximum perceived intensity of VII (Very strong) on the Modified Mercalli intensity scale in the towns of Yurimaguas and Lagunas.', 2019, 5, 26, NULL, NULL, NULL, 'day', '26 May 2019', 50, 'https://en.wikipedia.org/wiki/2019_Peru_earthquake'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q101444573', '2020 Peruvian protests', 'The 2020 Peruvian protests were a series of demonstrations sparked after the removal of President Martín Vizcarra that took place from 9 November to 17 November 2020. The controversial removal of Vizcarra was recognized as a coup d''état by many Peruvians, political analysts and media outlets in the country.', 2020, 11, 9, 2020, 11, 17, 'day', '9 November 2020 – 17 November 2020', 48, 'https://en.wikipedia.org/wiki/2020_Peruvian_protests'),
  ('Q109783491', '2021 Amazonas earthquake', 'A major earthquake struck northern Peru on November 28, 2021, 5:52 a.m. local time with a magnitude of 7.5 on the moment magnitude scale between the Amazonas and Loreto departments of Peru.', 2021, 11, 28, NULL, NULL, NULL, 'day', '28 November 2021', 43, 'https://en.wikipedia.org/wiki/2021_Northern_Peru_earthquake'),
  ('Q111465497', '2022 Peruvian protests', 'Mass protests in Peru against inflation and President Pedro Castillo''s government began in March 2022. The protests occurred amid rising fertilizer and fuel prices caused by Russia''s invasion of Ukraine and international sanctions imposed on Russia.', 2022, 3, 24, 2022, 12, NULL, 'day', '24 March 2022 – December 2022', 52, 'https://en.wikipedia.org/wiki/2022_Peruvian_economic_protests'),
  ('Q115277477', 'LATAM Perú Flight 2213', 'LATAM Airlines Perú Flight 2213 was a scheduled domestic passenger flight originating from Jorge Chávez International Airport, Lima, Peru, to Inca Manco Cápac International Airport, Juliaca, Peru. On 18 November 2022, the Airbus A320neo collided with a fire engine during its takeoff roll, killing two firefighters and seriously injuring a third, who died of his injuries seven months later.', 2022, 11, 18, NULL, NULL, NULL, 'day', '18 November 2022', 51, 'https://en.wikipedia.org/wiki/LATAM_Airlines_Per%C3%BA_Flight_2213'),
  ('Q115651756', '2022-2023 Peruvian protests', 'After President of Peru Pedro Castillo was ousted on 7 December 2022, a series of political protests against the government of President Dina Boluarte and the Congress of Peru occurred. The demonstrations lacked centralized leadership and originated primarily among grassroots movements and social organizations on the left to far-left, as well as indigenous communities, who felt politically disenfranchised.', 2022, 12, 7, 2023, 12, NULL, 'day', '7 December 2022 – December 2023', 55, 'https://en.wikipedia.org/wiki/Peruvian_protests_(2022%E2%80%932023)'),
  ('Q116157301', 'Juliaca massacre', 'The Juliaca massacre occurred on 9 January 2023, in the city of Juliaca, located in Peru’s Puno Department, amid widespread protests against President Dina Boluarte''s government. The event marked one of the deadliest confrontations during the 2022–2023 Peruvian political protests, which erupted following the ousting and imprisonment of former president Pedro Castillo.', 2023, 1, 9, NULL, NULL, NULL, 'day', '9 January 2023', 41, 'https://en.wikipedia.org/wiki/Juliaca_massacre'),
  ('Q132678951', 'Real Plaza Trujillo roof collapse', 'The Real Plaza Trujillo is a shopping mall located in the city of Trujillo, in the La Libertad Region of northern Peru. It is part of the Real Plaza chain operated by InRetail (Intercorp).', 2025, 2, 21, NULL, NULL, NULL, 'day', '21 February 2025', 37, 'https://en.wikipedia.org/wiki/Real_Plaza_Trujillo_roof_collapse'),
  ('Q136398794', '2025 Peruvian protests', 'On 20 September 2025, protests began in Peru against the administration of Dina Boluarte and the subsequent administration of José Jerí, following the impeachment of Dina Boluarte and the Congress of Peru. Protests against President Jerí grew following allegations of sexual assault against him.', 2025, 9, 27, NULL, NULL, NULL, 'day', '27 September 2025', 41, 'https://en.wikipedia.org/wiki/2025_Peruvian_protests');
